create table if not exists proof_review_participants (id uuid primary key, review_link_id uuid not null references proof_review_links(id) on delete cascade, client_name text not null, client_key_hash text not null, created_at timestamptz not null default now(), unique(review_link_id,client_key_hash));
create table if not exists proof_comments (id uuid primary key, project_id uuid not null references proof_projects(id) on delete cascade, deliverable_id uuid not null references proof_deliverables(id) on delete cascade, version_id uuid not null references proof_versions(id) on delete cascade, participant_id uuid not null references proof_review_participants(id) on delete cascade, body text not null check(length(body) between 1 and 2000), created_at timestamptz not null default now());
create table if not exists proof_favorites (participant_id uuid not null references proof_review_participants(id) on delete cascade, version_id uuid not null references proof_versions(id) on delete cascade, created_at timestamptz not null default now(), primary key(participant_id,version_id));
create table if not exists proof_revision_requests (id uuid primary key, project_id uuid not null references proof_projects(id) on delete cascade, deliverable_id uuid not null references proof_deliverables(id) on delete cascade, version_id uuid not null references proof_versions(id) on delete cascade, participant_id uuid not null references proof_review_participants(id) on delete cascade, body text not null check(length(body) between 1 and 2000), status text not null default 'Open' check(status in ('Open','Addressed')), created_at timestamptz not null default now(), addressed_at timestamptz);
create table if not exists proof_approvals (id uuid primary key, project_id uuid not null references proof_projects(id) on delete cascade, deliverable_id uuid not null references proof_deliverables(id) on delete cascade, version_id uuid not null references proof_versions(id) on delete cascade, participant_id uuid not null references proof_review_participants(id) on delete cascade, created_at timestamptz not null default now(), unique(participant_id,version_id));
create index if not exists proof_comments_project on proof_comments(project_id,created_at);
